CREATE TABLE tuple_target(id INTEGER PRIMARY KEY,a,b,c,d); INSERT INTO tuple_target VALUES(1,10,20,0,0),(2,30,40,0,0); CREATE TABLE tuple_source(id,delta); INSERT INTO tuple_source VALUES(1,3),(2,5); UPDATE tuple_target AS t SET (a,b)=(SELECT t.a+s.delta,t.b+s.delta),c=99 FROM tuple_source AS s WHERE t.id=s.id; SELECT * FROM tuple_target ORDER BY id;
UPDATE tuple_target SET (a,b)=(SELECT delta,id FROM tuple_source WHERE 0) FROM tuple_source AS s WHERE tuple_target.id=s.id; SELECT * FROM tuple_target ORDER BY id;
UPDATE tuple_target SET (a,b)=(SELECT 1,2,3) FROM tuple_source; SELECT * FROM tuple_target ORDER BY id;
UPDATE tuple_target SET (a,b)=(SELECT 11,12),(c,d)=(SELECT 11,12) FROM tuple_source; SELECT * FROM tuple_target ORDER BY id;
CREATE TABLE cte_target(a); INSERT INTO cte_target VALUES(1); CREATE TABLE cte_source(x); INSERT INTO cte_source VALUES(2); WITH cte_target AS (SELECT 100 AS a) UPDATE cte_target SET a=(SELECT a FROM cte_target)+x FROM cte_source; SELECT * FROM cte_target;
CREATE TEMP TABLE temp_target(a); INSERT INTO temp_target VALUES(7); WITH temp_target AS (SELECT 100 AS a) UPDATE temp_target AS t SET a=t.a+x FROM cte_source; SELECT * FROM temp_target;
CREATE TABLE view_base(id,a,b); INSERT INTO view_base VALUES(1,10,20); CREATE VIEW update_view AS SELECT * FROM view_base; CREATE TABLE view_log(olda,newa,oldb,newb); CREATE TRIGGER update_view_trigger INSTEAD OF UPDATE ON update_view BEGIN INSERT INTO view_log VALUES(old.a,new.a,old.b,new.b); UPDATE view_base SET a=new.a,b=new.b+1 WHERE id=old.id; END; CREATE TABLE duplicate_source(id,delta); INSERT INTO duplicate_source VALUES(1,3),(1,4); UPDATE update_view AS v SET a=v.a+s.delta FROM duplicate_source AS s WHERE v.id=s.id; SELECT * FROM view_base; SELECT * FROM view_log;
CREATE TABLE join_target(id INTEGER PRIMARY KEY,x,y); INSERT INTO join_target VALUES(1,101,201),(2,102,202),(3,103,203); CREATE TABLE join_left(id,x); INSERT INTO join_left VALUES(1,11); CREATE TABLE join_right(id,y); INSERT INTO join_right VALUES(1,21),(2,22); UPDATE join_target AS t SET x=l.x,y=r.y FROM join_left AS l RIGHT JOIN join_right AS r USING(id) WHERE t.id=r.id; SELECT * FROM join_target ORDER BY id;
INSERT INTO join_left VALUES(3,13); UPDATE join_target AS t SET x=l.x,y=r.y FROM join_left AS l FULL JOIN join_right AS r USING(id) WHERE t.id=l.id OR t.id=r.id; SELECT * FROM join_target ORDER BY id;
UPDATE join_target AS t SET x=l.x,y=r.y FROM join_left AS l NATURAL LEFT JOIN join_right AS r WHERE t.id=l.id; SELECT * FROM join_target ORDER BY id;
CREATE TABLE volatile_target(id PRIMARY KEY,a,b); INSERT INTO volatile_target VALUES(1,0,0),(2,0,0); UPDATE volatile_target AS t SET (a,b)=(SELECT r,r FROM (SELECT random()+t.id AS r)) FROM duplicate_source; SELECT id,a=b AS same_value FROM volatile_target ORDER BY id;
ATTACH ':memory:' AS aux; CREATE TABLE aux.att_target(id PRIMARY KEY,v); INSERT INTO aux.att_target VALUES(1,0),(2,0); CREATE TABLE att_source(id,v); INSERT INTO att_source VALUES(1,100),(2,200); UPDATE aux.att_target AS t SET v=s.v FROM att_source AS s WHERE t.id=s.id; SELECT * FROM aux.att_target ORDER BY id;
CREATE TABLE shadow_target(a); INSERT INTO main.shadow_target VALUES(1); CREATE TEMP TABLE shadow_target(a); INSERT INTO temp.shadow_target VALUES(9); WITH shadow_target AS (SELECT 500 AS a) UPDATE main.shadow_target AS t SET a=t.a+x FROM cte_source; SELECT * FROM main.shadow_target; SELECT * FROM temp.shadow_target;
UPDATE tuple_target SET (a,b)=(SELECT 21,22),(c,d)=(SELECT 21,22); SELECT * FROM tuple_target ORDER BY id;
